  color: var(--color-text-muted);
  margin-bottom: var(--spacing-xl);
}

/* Product Grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: var(--spacing-xl);
}

.product-card article {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.product-image {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius-md);
  overflow: hidden;
  background-color: var(--color-secondary);
  margin-bottom: var(--spacing-md);
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.badge {
  position: absolute;
  top: var(--spacing-sm);
  left: var(--spacing-sm);
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  font-weight: bold;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  z-index: 10;
}

.badge.sale {
  background-color: var(--color-sale);
  color: white;
}

.product-info {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-title {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-xs);
}

.product-title a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product-card article { position: relative; }
/* Make button above the clickable link layer */
.product-card .button {
  position: relative;
  z-index: 2;
  margin-top: auto;
  width: 100%;
}

.product-price {
  font-weight: 600;
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-md);
}

.original-price {
  color: var(--color-text-muted);
  margin-right: var(--spacing-sm);
  font-weight: normal;
}

.sale-price {
  color: var(--color-sale);
  font-weight: 700;
}

/* Editorial Grid */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-xl);
}

.editorial-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  height: 100%;
  display: flex;
  flex-direction: column;
}

.editorial-card img {
  width: 100%;
  aspect-ratio: 3/2;
  object-fit: cover;
}

.editorial-content {
  padding: var(--spacing-lg);
  flex: 1;
  display: flex;
  flex-direction: column;
}

.editorial-content p {
  color: var(--color-text-muted);
  flex: 1;
}

/* Footer */
.site-footer {
  background-color: var(--color-primary);
  color: white;
  padding-top: var(--spacing-2xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
  margin-bottom: var(--spacing-2xl);
}

.footer-brand {
  font-size: 1.5rem;
  margin-bottom: var(--spacing-sm);
}

.footer-col p, .footer-col a {
  color: #9ca3af;
}

.footer-col h3 {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-md);
}

.footer-col li {
  margin-bottom: var(--spacing-sm);
}

.footer-col a:hover, .footer-col a:focus {
  color: white;
  text-decoration: underline;
}

.footer-bottom {
  border-top: 1px solid var(--color-primary-hover);
  padding: var(--spacing-lg) 0;
  text-align: center;
  color: #9ca3af;
}
.footer-bottom p {
  margin: 0;
}

/* Responsive */
@media (max-width: 768px) {
  .main-nav {
    display: none; /* In a real app, this would be a hamburger menu */
  }
}
