document.addEventListener('DOMContentLoaded', () => {
  // Search Toggle
  const searchToggleBtn = document.getElementById('search-toggle');
  const searchFormContainer = document.getElementById('search-form');
  const searchInput = document.getElementById('search-input');

  searchToggleBtn.addEventListener('click', () => {
    const isExpanded = searchToggleBtn.getAttribute('aria-expanded') === 'true';

    if (isExpanded) {
      // Close search
      searchToggleBtn.setAttribute('aria-expanded', 'false');
      searchFormContainer.hidden = true;
    } else {
      // Open search
      searchToggleBtn.setAttribute('aria-expanded', 'true');
      searchFormContainer.hidden = false;
      // Focus input after rendering
      setTimeout(() => searchInput.focus(), 50);
    }
  });

  // Close search on escape key
  searchInput.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      searchToggleBtn.setAttribute('aria-expanded', 'false');
      searchFormContainer.hidden = true;
      searchToggleBtn.focus();
    }
  });

  // Cart Functionality
  const addToCartButtons = document.querySelectorAll('.add-to-cart');
  const cartBadge = document.getElementById('cart-badge');
  const cartCountText = document.getElementById('cart-count-text');
  const liveRegion = document.getElementById('live-region');

  let cartCount = 0;

  addToCartButtons.forEach(button => {
    button.addEventListener('click', (e) => {
      // Prevent the click from bubbling to the article link
      e.preventDefault();

      const productName = button.getAttribute('data-product');
      cartCount++;

      // Update visual and accessible cart state
      cartBadge.textContent = cartCount;
      const itemCountText = cartCount === 1 ? '1 item' : `${cartCount} items`;
      cartCountText.textContent = itemCountText;

      // Announce to screen readers
      liveRegion.textContent = `Added ${productName} to cart. Cart now has ${itemCountText}.`;

      // Clear live region after short delay to allow subsequent identical announcements
      setTimeout(() => {
        liveRegion.textContent = '';
      }, 3000);
    });
  });
});
